{
  "name": "tenants.get-user-tenants",
  "kind": "read",
  "description": "List the tenants one user is a member of, ordered by tenant identifier, with each tenant\u0027s name, status and the user\u0027s role. Callers always see their own memberships, a global administrator sees any user\u0027s, and a TenantOwner sees another user\u0027s memberships only in tenants the caller owns. Memberships the caller may not see are left out, so the list can be empty. Results are paged: pageSize takes 1 to 100 (default 20, larger values are reduced to 100); to read the next page, pass the returned next-page cursor as the cursor argument: it is the result document\u0027s cursor, also reported as paging.nextCursor when a paging argument was sent. offset is not supported.",
  "schema": {
    "type": [
      "object",
      "null"
    ],
    "properties": {
      "UserId": {
        "type": "string",
        "description": "Identifier of the user whose memberships are listed: the subject (sub) claim the identity provider issues for that user. Always set it, including for your own memberships: an omitted UserId does not default to you and usually returns an empty list. To list your own tenants without knowing your subject, use tenants.list-tenants; it returns no roles, and a global administrator gets every tenant there."
      },
      "Cursor": {
        "type": [
          "string",
          "null"
        ],
        "description": "Has no effect: use the pageSize and cursor call arguments instead."
      },
      "PageSize": {
        "type": "integer",
        "description": "Has no effect: use the pageSize and cursor call arguments instead."
      }
    },
    "additionalProperties": false
  },
  "example": {
    "UserId": "8d3f2a61-5b7e-4c0a-9e21-3f4b6c7d8e90"
  },
  "envelope": {
    "fixedTenant": "system",
    "aggregateIdRequired": false,
    "idempotencyKeyRequired": false,
    "arguments": [
      "aggregateId",
      "entityId",
      "pageSize",
      "offset",
      "cursor"
    ]
  },
  "lintFindings": [
    {
      "code": "payload_paging_member",
      "severity": "warning",
      "message": "Move paging member Cursor to the query envelope argument.",
      "property": "/properties/Cursor"
    },
    {
      "code": "payload_paging_member",
      "severity": "warning",
      "message": "Move paging member PageSize to the query envelope argument.",
      "property": "/properties/PageSize"
    }
  ],
  "submittable": false,
  "reason": "configuration_invalid"
}
